import{_ as o,o as t,c as r,ag as a}from"./chunks/framework.Cyu1VozZ.js";const u=JSON.parse('{"title":"Organizing with Folders","description":"","frontmatter":{},"headers":[],"relativePath":"pdf/organizing-with-folders.md","filePath":"pdf/organizing-with-folders.md"}'),s={name:"pdf/organizing-with-folders.md"};function n(i,e,l,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="organizing-with-folders" tabindex="-1">Organizing with Folders <a class="header-anchor" href="#organizing-with-folders" aria-label="Permalink to &quot;Organizing with Folders&quot;">​</a></h1><p>Folders let you organize a workspace&#39;s documents into a tree — the same way a Shared Drive works. Folders are <strong>purely organizational</strong>: they group documents for browsing but do not change who can access a document.</p><p>Every document type can live in a folder — sheets, docs, slides, notes, boards, PDFs, images, and any other file you&#39;ve uploaded.</p><h2 id="create-a-folder" tabindex="-1">Create a folder <a class="header-anchor" href="#create-a-folder" aria-label="Permalink to &quot;Create a folder&quot;">​</a></h2><ol><li>Open your workspace</li><li>Click the <strong>New</strong> dropdown button</li><li>Select <strong>New folder</strong></li><li>Give it a name</li></ol><p>The new folder is created inside whichever folder you&#39;re currently browsing, so folders nest to any depth and you can build a structure like <code>Team → Projects → 2026</code>.</p><div class="tip custom-block"><p class="custom-block-title">Folders need a workspace</p><p><strong>New folder</strong> appears only when you&#39;re looking at a single workspace&#39;s list. The combined list of every workspace&#39;s documents has no one workspace to create the folder in, so the entry isn&#39;t offered there — switch to a workspace first.</p></div><h2 id="move-documents-and-folders" tabindex="-1">Move documents and folders <a class="header-anchor" href="#move-documents-and-folders" aria-label="Permalink to &quot;Move documents and folders&quot;">​</a></h2><ul><li><strong>Drag a document onto a folder row</strong> to move it there. Select several first and the whole selection moves together. You can also drop onto a segment of the breadcrumb to move a document back up the tree.</li><li>Use <strong>Move to…</strong> in a row&#39;s <strong>⋯</strong> menu to do the same through a dialog — which is also how you move a <em>document</em> into a different workspace.</li><li>Moving a folder brings all of its contents along with it.</li></ul><div class="warning custom-block"><p class="custom-block-title">Folders never leave their workspace</p><p>The <strong>Move to…</strong> dialog lets you pick another workspace, but that only applies to documents. Ask it to move a folder there and the folder stays where it is — you&#39;re told &quot;Folders can&#39;t move to another workspace&quot; and only the documents in the selection move.</p></div><p>Moving is limited to documents you created, unless you own the workspace: a row you don&#39;t manage can&#39;t be picked up at all, and a multi-selection containing one is refused with a message instead of moving the rest. Moving a <em>folder</em> follows the same rule, but — as with deleting one — the menu entry is shown to everyone: <strong>Move to…</strong> is offered on every folder row, so a member moving a folder they neither created nor own the workspace for gets a &quot;Failed to move&quot; message rather than a missing button. See <a href="/docs/guide/workspaces.html#roles">Workspaces &amp; Members</a> for who counts as what.</p><h2 id="browse-folders" tabindex="-1">Browse folders <a class="header-anchor" href="#browse-folders" aria-label="Permalink to &quot;Browse folders&quot;">​</a></h2><ul><li><strong>Click a folder</strong> to drill into it and see the documents inside.</li><li>The <strong>breadcrumb</strong> at the top shows where you are; click any segment to jump back up the tree.</li><li>The workspace root is the top level — documents that aren&#39;t in any folder live there.</li></ul><h2 id="rename-a-folder" tabindex="-1">Rename a folder <a class="header-anchor" href="#rename-a-folder" aria-label="Permalink to &quot;Rename a folder&quot;">​</a></h2><p>Open the folder row&#39;s <strong>⋯</strong> menu and choose <strong>Rename</strong>. Any member of the workspace can rename any folder — renaming is the one folder action that isn&#39;t restricted to the person who created it.</p><h2 id="delete-a-folder" tabindex="-1">Delete a folder <a class="header-anchor" href="#delete-a-folder" aria-label="Permalink to &quot;Delete a folder&quot;">​</a></h2><p><strong>Delete</strong> in the same <strong>⋯</strong> menu removes the folder and its sub-folders, but <strong>never deletes your documents</strong> — any documents inside return to the workspace root so nothing is lost.</p><p>Unlike renaming, deleting is restricted: you can delete folders you created, and a workspace owner can delete any of them. The menu entry is shown to everyone, so a member deleting someone else&#39;s folder gets a &quot;Failed to delete&quot; message rather than a missing button. See <a href="/docs/guide/workspaces.html#roles">Workspaces &amp; Members</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Folders only organize documents; they don&#39;t grant or restrict access. Sharing and permissions are controlled per-document — see <a href="/docs/guide/collaboration.html">Collaboration &amp; Sharing</a>.</p></div>',19)])])}const g=o(s,[["render",n]]);export{u as __pageData,g as default};
